// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the computation was successful.
* -   if less than zero, then the `-i`th argument had an illegal value.
*/
type StatusCode = number;

/**
* Interface describing `dgeqrf`.
*/
interface Routine {
	/**
	* Computes a QR factorization of a real M-by-N matrix `A`.
	*
	* @param order - storage layout
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input/output matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param TAU - output array of scalar factors (length `min(M,N)`)
	* @param WORK - workspace array (length >= `M`)
	* @param LWORK - dimension of the array `WORK`
	* @returns status code (0 if successful)
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 5.0, 9.0, 2.0, 6.0, 10.0, 3.0, 7.0, 11.0, 4.0, 8.0, 12.0 ] );
	* var TAU = new Float64Array( 3 );
	* var WORK = new Float64Array( 4 );
	*
	* var info = dgeqrf( 'column-major', 3, 4, A, 3, TAU, WORK, 4 );
	* // returns 0
	*/
	( order: Layout, M: number, N: number, A: Float64Array, LDA: number, TAU: Float64Array, WORK: Float64Array, LWORK: number ): StatusCode;

	/**
	* Computes a QR factorization of a real M-by-N matrix `A` using alternative indexing semantics.
	*
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input/output matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param TAU - output array of scalar factors (length `min(M,N)`)
	* @param strideTAU - stride for TAU
	* @param offsetTAU - starting index for TAU
	* @param WORK - workspace array (length >= `M`)
	* @param strideWORK - stride for `WORK`
	* @param offsetWORK - starting index for `WORK`
	* @param LWORK - dimension of the array `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 5.0, 9.0, 2.0, 6.0, 10.0, 3.0, 7.0, 11.0, 4.0, 8.0, 12.0 ] );
	* var TAU = new Float64Array( 3 );
	* var WORK = new Float64Array( 4 );
	*
	* var info = dgeqrf.ndarray( 3, 4, A, 1, 3, 0, TAU, 1, 0, WORK, 1, 0, 4 );
	* // returns 0
	*/
	ndarray( M: number, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, TAU: Float64Array, strideTAU: number, offsetTAU: number, WORK: Float64Array, strideWORK: number, offsetWORK: number, LWORK: number ): StatusCode;
}

/**
* LAPACK routine to compute a QR factorization of a real M-by-N matrix `A`.
*
* @param order - storage layout
* @param M - number of rows in `A`
* @param N - number of columns in `A`
* @param A - input/output matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param TAU - output array of scalar factors (length `min(M,N)`)
* @param WORK - workspace array (length >= `M`)
* @param LWORK - dimension of the array `WORK`
* @returns status code (0 if successful)
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 5.0, 9.0, 2.0, 6.0, 10.0, 3.0, 7.0, 11.0, 4.0, 8.0, 12.0 ] );
* var TAU = new Float64Array( 3 );
* var WORK = new Float64Array( 4 );
*
* var info = dgeqrf( 'column-major', 3, 4, A, 3, TAU, WORK, 4 );
* // returns 0
*
* @example
* // ndarray interface:
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 5.0, 9.0, 2.0, 6.0, 10.0, 3.0, 7.0, 11.0, 4.0, 8.0, 12.0 ] );
* var TAU = new Float64Array( 3 );
* var WORK = new Float64Array( 4 );
*
* var info = dgeqrf.ndarray( 3, 4, A, 1, 3, 0, TAU, 1, 0, WORK, 1, 0, 4 );
* // returns 0
*/
declare var dgeqrf: Routine;


// EXPORTS //

export = dgeqrf;
